import { Component } from '@angular/core';
import { UsuarioService } from 'src/app/services/usuario.service';
import { MisComprasService } from 'src/app/services/mis-compras.service';

@Component({
  selector: 'app-ejercicio46',
  templateUrl: './ejercicio46.component.html',
  styleUrls: ['./ejercicio46.component.css']
})
export class Ejercicio46Component {

  public productoCaro: string = '';
  public hayError: boolean = false;


 constructor(private misComprasService: MisComprasService, private usuarioService: UsuarioService) { }

}
<div class="container">
  <button class="btn btn-primary" (click)="mostrarProductoMasCaro()">Mostrar Producto Más Caro</button>
  <div *ngIf="productoCaro">
    <p>El producto más caro vendido: {{ productoCaro }}</p>
  </div>
  <div *ngIf="hayError">
    <p>Error: No se pudo cargar el producto más caro.</p>
  </div>
</div>
